// Package autocomplete предоставляет сервис автодополнения поисковых запросов,
// основанный на префиксном дереве (trie) с учётом популярности запросов.
package autocomplete

import (
	"sort"
	"strings"
	"sync"
	"unicode/utf8"
)

// TrieNode представляет узел префиксного дерева.
// Каждый узел хранит:
//   - children: карту дочерних узлов по символам
//   - isEnd: флаг, указывающий, что данный узел является концом полного слова
//   - popularity: числовое значение популярности слова, заканчивающегося в этом узле
type TrieNode struct {
	children   map[rune]*TrieNode
	isEnd      bool
	popularity int
}

// NewTrieNode создаёт новый пустой узел префиксного дерева.
func NewTrieNode() *TrieNode {
	return &TrieNode{
		children:   make(map[rune]*TrieNode),
		isEnd:      false,
		popularity: 0,
	}
}

// AutocompleteService — основной сервис автодополнения.
// Он использует префиксное дерево для хранения слов и их популярности,
// а также предоставляет потокобезопасный API для добавления слов и получения подсказок.
type AutocompleteService struct {
	root *TrieNode
	mu   sync.RWMutex
}

// NewAutocompleteService создаёт новый экземпляр сервиса автодополнения.
// Возвращает указатель на инициализированный сервис с пустым корнем дерева.
func NewAutocompleteService() *AutocompleteService {
	return &AutocompleteService{
		root: NewTrieNode(),
	}
}

// AddWord добавляет слово в префиксное дерево с указанной популярностью.
// Если слово уже существует, его популярность обновляется (перезаписывается).
// Пустые строки игнорируются.
// Метод потокобезопасен.
func (s *AutocompleteService) AddWord(word string, popularity int) {
	// Игнорируем пустые слова
	if word == "" {
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	current := s.root
	for _, r := range word {
		// Если дочерний узел для текущего символа не существует, создаём его
		if _, exists := current.children[r]; !exists {
			current.children[r] = NewTrieNode()
		}
		current = current.children[r]
	}
	// Помечаем узел как конец слова и устанавливаем популярность
	current.isEnd = true
	current.popularity = popularity
}

