public List<Pick> allocate(String sku, int qty, List<Bin> bins) {
    // Проверяем, что запрошенное количество положительное.
    // Если qty <= 0, выбрасываем исключение, так как выделять ноль или отрицательное количество бессмысленно.
    if (qty <= 0) throw new IllegalArgumentException("qty must be positive");

    // Фильтруем список ячеек хранения (bins), оставляя только те, которые:
    // 1. Содержат нужный SKU (идентификатор товара).
    // 2. Имеют доступное количество (available > 0).
    // Затем сортируем оставшиеся ячейки по дате истечения срока годности (expiresAt) по возрастанию.
    // Это реализует стратегию FEFO (First Expired, First Out) — сначала отгружаем товары с ближайшим сроком годности.
    List<Bin> candidates = bins.stream()
        .filter(b -> b.getSku().equals(sku) && b.getAvailable() > 0)
        .sorted(Comparator.comparing(Bin::getExpiresAt))
        .collect(Collectors.toList());

    // Создаем список для хранения результатов распределения (пикеров/выборок).
    List<Pick> picks = new ArrayList<>();

    // Инициализируем переменную left, которая будет отслеживать оставшееся количество товара, которое нужно выделить.
    int left = qty;

    // Итерируемся по отсортированным кандидатам (ячейкам с подходящим товаром).
    for (Bin b : candidates) {
        // Если все необходимое количество уже выделено, прерываем цикл.
        if (left == 0) break;

        // Определяем, сколько товара можно взять из текущей ячейки:
        // берем минимум между оставшимся требуемым количеством (left) и доступным количеством в ячейке (b.getAvailable()).
        int take = Math.min(left, b.getAvailable());

        // Создаем объект Pick, указывая ID ячейки и количество, которое из нее берем, и добавляем в список picks.
        picks.add(new Pick(b.getId(), take));

        // Уменьшаем оставшееся требуемое количество на взятое из текущей ячейки.
        left -= take;
    }

    // После прохода по всем кандидатам проверяем, осталось ли невыделенное количество.
    // Если left > 0, значит, суммарного доступного количества по всем ячейкам не хватило для выполнения заказа.
    // В этом случае выбрасываем исключение InsufficientStockException, указывая SKU, фактически выделенное количество (qty - left) и запрошенное количество (qty).
    if (left > 0) throw new InsufficientStockException(sku, qty - left, qty);

    // Возвращаем список сформированных пикеров (распределений товара по ячейкам).
    return picks;
}
