func (idx *Index) Search(query string, limit int) []int {
    terms := tokenize(query)
    if len(terms) == 0 || limit <= 0 {
        return nil
    }
    result, ok := idx.postings[terms[0]]
    if !ok {
        return nil
    }
    for _, term := range terms[1:] {
        result = intersect(result, idx.postings[term])
        if len(result) == 0 {
            return nil
        }
    }
    if len(result) > limit {
        result = result[:limit]
    }
    return result
}
