/**
 * Функция переранжирования кандидатов с учетом ограничений.
 *
 * @param candidates - Список кандидатов для ранжирования.
 * @param purchased - Множество идентификаторов товаров, которые пользователь уже купил (их нужно исключить).
 * @param maxPerCategory - Максимальное количество кандидатов, которые можно взять из одной категории.
 * @param limit - Общее максимальное количество кандидатов в итоговом списке.
 * @returns Отранжированный и отфильтрованный список кандидатов.
 */
export function rerank(
  candidates: Candidate[],
  purchased: Set<string>,
  maxPerCategory: number,
  limit: number,
): Candidate[] {
  // Создаем карту для подсчета количества выбранных кандидатов по каждой категории.
  // Ключ — название категории, значение — сколько кандидатов из этой категории уже добавлено в результат.
  const perCategory = new Map<string, number>();

  // Массив для хранения итогового отранжированного списка кандидатов.
  const result: Candidate[] = [];

  // Создаем копию массива кандидатов и сортируем его по убыванию оценки (score).
  // Это гарантирует, что мы сначала рассматриваем наиболее релевантные/высокооцененные кандидаты.
  // Копия создается через spread-оператор [...candidates], чтобы не мутировать исходный массив.
  for (const c of [...candidates].sort((a, b) => b.score - a.score)) {
    // Пропускаем кандидата, если его товар уже был куплен пользователем.
    if (purchased.has(c.itemId)) continue;

    // Получаем текущее количество кандидатов, уже добавленных из категории этого кандидата.
    // Если категории еще нет в карте, используем 0 как значение по умолчанию.
    const used = perCategory.get(c.category) ?? 0;

    // Пропускаем кандидата, если из его категории уже выбрано максимальное допустимое количество кандидатов.
    if (used >= maxPerCategory) continue;

    // Увеличиваем счетчик выбранных кандидатов для категории текущего кандидата.
    perCategory.set(c.category, used + 1);

    // Добавляем кандидата в итоговый список.
    result.push(c);

    // Если мы уже собрали достаточное количество кандидатов (достигли лимита),
    // прерываем цикл, так как дальнейшие кандидаты не нужны.
    if (result.length === limit) break;
  }

  // Возвращаем итоговый отранжированный и отфильтрованный список кандидатов.
  return result;
}
```

