```kotlin
fun planLoads(orders: List<Order>, capacityKg: Double): List<List<Order>> {
    // Проверяем, что грузоподъёмность положительная, иначе задача не имеет смысла
    require(capacityKg > 0) { "capacityKg must be positive" }

    // Находим заказы, вес которых превышает максимальную грузоподъёмность одного рейса
    val oversized = orders.filter { it.weightKg > capacityKg }
    // Если такие заказы есть, выбрасываем исключение, так как их невозможно перевезти
    if (oversized.isNotEmpty()) {
        throw IllegalArgumentException("orders exceed capacity: ${oversized.map { it.id }}")
    }

    // Список рейсов (грузов), где каждый рейс — это список заказов
    val loads = mutableListOf<MutableList<Order>>()
    // Список оставшейся свободной грузоподъёмности для каждого рейса
    val free = mutableListOf<Double>()

    // Сортируем заказы по убыванию веса (алгоритм First Fit Decreasing)
    // Это помогает более эффективно упаковывать крупные заказы первыми
    for (order in orders.sortedByDescending { it.weightKg }) {
        // Ищем первый рейс, в который помещается текущий заказ
        val i = free.indexOfFirst { it >= order.weightKg }
        if (i >= 0) {
            // Если такой рейс найден, добавляем заказ в него
            loads[i].add(order)
            // Уменьшаем свободную грузоподъёмность этого рейса на вес добавленного заказа
            free[i] -= order.weightKg
        } else {
            // Если ни в один существующий рейс заказ не помещается, создаём новый рейс
            loads.add(mutableListOf(order))
            // Инициализируем свободную грузоподъёмность нового рейса
            free.add(capacityKg - order.weightKg)
        }
    }

    // Возвращаем список сформированных рейсов
    return loads
}
