/// Вычисляет оценку релевантности документа для заданного термина с использованием алгоритма BM25.
///
/// # Аргументы
/// * `tf` - частота термина в текущем документе (term frequency).
/// * `doc_len` - длина текущего документа (обычно количество слов или токенов).
/// * `avg_len` - средняя длина всех документов в коллекции.
/// * `df` - количество документов, содержащих данный термин (document frequency).
/// * `n_docs` - общее количество документов в коллекции.
///
/// # Возвращаемое значение
/// * `f64` - итоговый балл BM25 для данного термина в данном документе.
pub fn bm25(tf: u32, doc_len: u32, avg_len: f64, df: u32, n_docs: u32) -> f64 {
    // Параметры настройки алгоритма BM25:
    // K1 контролирует влияние частоты термина (tf) на итоговый балл.
    // B контролирует влияние длины документа на нормализацию.
    const K1: f64 = 1.2;
    const B: f64 = 0.75;

    // Если термина нет в документе (tf == 0) или коллекция пуста (n_docs == 0),
    // то вклад этого термина в релевантность равен нулю.
    if tf == 0 || n_docs == 0 {
        return 0.0;
    }

    // Вычисление обратной частоты документа (IDF - Inverse Document Frequency).
    // IDF измеряет важность термина: чем реже термин встречается в коллекции,
    // тем выше его вес. Формула использует сглаживание (+0.5) для избежания деления на ноль
    // и логарифм для уменьшения влияния очень частых терминов.
    let idf = ((n_docs as f64 - df as f64 + 0.5) / (df as f64 + 0.5)).ln();

    // Вычисление нормализующего коэффициента для длины документа.
    // Этот коэффициент корректирует балл в зависимости от того, насколько длина
    // текущего документа отличается от средней длины коллекции.
    // Если документ длиннее среднего, нормализующий коэффициент увеличивается,
    // что снижает итоговый балл (чтобы длинные документы не получали несправедливое преимущество).
    let norm = 1.0 - B + B * doc_len as f64 / avg_len;

    // Преобразуем частоту термина из целочисленного типа в вещественный для дальнейших вычислений.
    let tf = tf as f64;

    // Итоговая формула BM25:
    // Балл рассчитывается как произведение IDF на нормализованную частоту термина.
    // Часть `tf * (K1 + 1.0) / (tf + K1 * norm)` представляет собой насыщающуюся функцию
