func Snippet(s string, maxRunes int) string {
    // Преобразуем строку в срез рун, чтобы работать с символами, а не байтами.
    runes := []rune(s)

    // Если длина строки в символах меньше или равна maxRunes, возвращаем всю строку.
    if len(runes) <= maxRunes {
